import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第三册：培养技能 · Lesson 4 The double life of Alfred Bloggs","description":"学习 used to 与过去习惯，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 4 The double life of Alfred Bloggs","description":"学习 used to 与过去习惯，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 used to 与过去习惯，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 3 An unknown goddess","link":"/life/english/new-concept/book-3/unit-01/lesson-003"},"next":{"text":"第三册：培养技能 · Lesson 5 The facts","link":"/life/english/new-concept/book-3/unit-01/lesson-005"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 3 An unknown goddess","link":"/life/english/new-concept/book-3/unit-01/lesson-003"},"next":{"text":"第三册：培养技能 · Lesson 5 The facts","link":"/life/english/new-concept/book-3/unit-01/lesson-005"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-01/lesson-004.md","filePath":"life/english/new-concept/book-3/unit-01/lesson-004.md"}'),i={name:"life/english/new-concept/book-3/unit-01/lesson-004.md"};function s(l,e,r,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-lesson-4-the-double-life-of-alfred-bloggs" tabindex="-1">第三册：培养技能 · Lesson 4 The double life of Alfred Bloggs <a class="header-anchor" href="#第三册-培养技能-·-lesson-4-the-double-life-of-alfred-bloggs" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 4 The double life of Alfred Bloggs&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从职业身份与社会评价的反差切入，练习描述长期习惯及过去习惯的变化。讨论工作时把实际职责和外界印象分开，不把职业高低当作语法例句的默认前提。学习使用 used to 说明现在已经改变的状态，并用具体行为支持人物描写。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>occupation</td><td>/ˌɒkjʊˈpeɪʃən/</td><td>n.</td><td>职业</td><td>state your occupation</td></tr><tr><td>uniform</td><td>/ˈjuːnɪfɔːm/</td><td>n.</td><td>制服</td><td>wear a uniform</td></tr><tr><td>status</td><td>/ˈsteɪtəs/</td><td>n.</td><td>地位</td><td>social status</td></tr><tr><td>conceal</td><td>/kənˈsiːl/</td><td>v.</td><td>隐瞒</td><td>conceal a fact</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>earn a living — 谋生，后面可接 by doing</li><li>be proud of — 为某事或某人感到自豪</li></ul><h2 id="语法讲解-used-to-与过去习惯" tabindex="-1">语法讲解：used to 与过去习惯 <a class="header-anchor" href="#语法讲解-used-to-与过去习惯" aria-label="Permalink to &quot;语法讲解：used to 与过去习惯&quot;">​</a></h2><p>used to 后接动词原形，表示过去经常发生而现在通常不再发生的动作，也可描述过去状态。would 也能叙述过去反复动作，但通常需要先建立过去时间背景，且一般不直接替代 used to 描述静态事实。否定和疑问常写 didn&#39;t use to 与 Did ... use to。be used to 后接名词或动名词，表示习惯于某事，和 used to do 的意义、结构都不同；两者不能仅凭中文“习惯”互换。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Leo used to hide his work clothes, but now he talks openly about his job.</p></blockquote><p>利奥过去会藏起工作服，现在却坦然谈论自己的工作。</p><p>used to hide 表示已改变的习惯；but now 与前半句构成明确时间对比。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>I am used to work early 应改为 I am used to working early；若说过去早上班，则是 I used to work early。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对比朗读 used to hide 与 is used to hiding，重点听第二个结构中 is 和 hiding，防止只听到相似的 used to 就误判。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Mia used to avoid questions about her cleaning job. A grateful customer changed her view of the work. She now introduces herself with confidence.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>描述一个人对职业看法的变化，包含过去习惯、转折原因和现在的态度。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>用具体事件解释态度变化，避免只贴性格标签。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>把例句的 hide 改成否定过去习惯。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Leo didn&#39;t use to hide his work clothes.</p><p><strong>解析：</strong> didn&#39;t 后 use 保持原形。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：She is used to ___ a uniform.（wear/wearing）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> wearing</p><p><strong>解析：</strong> be used to 中 to 为介词。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>例句是否说明利奥现在仍藏工作服？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不是。</p><p><strong>解析：</strong> but now 引出行为转变。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：used to 与过去习惯。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-003">上一课</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-01/lesson-005">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(i,[["render",s]]);export{p as __pageData,b as default};
